		(function() {

			let currentIndex = 0;
			let currentModalIndex = 0;
			const track = document.getElementById('cc-track');
			const modal = document.getElementById('cc-modal');
			const modalImg = document.getElementById('cc-modal-img');


			const getImages = () => document.querySelectorAll('.custom-carousel-item img');
			const totalItems = getImages().length;


			function isMobile() {
				return window.innerWidth < 768;
			}

			function updateLayout() {
				const showNum = isMobile() ? 1 : 3;


				if (totalItems < showNum) {
					track.style.justifyContent = 'center';
				} else {
					track.style.justifyContent = 'flex-start';
				}
			}


			updateLayout();
			window.addEventListener('resize', updateLayout);


			window.ccMove = function(direction) {
				const showNum = isMobile() ? 1 : 3;
				const itemWidthPercent = 100 / showNum;

				let newIndex = currentIndex + direction;


				if (newIndex < 0) newIndex = 0;
				const maxIndex = Math.max(0, totalItems - showNum);
				if (newIndex > maxIndex) newIndex = maxIndex;

				currentIndex = newIndex;
				track.style.transform = `translateX(-${currentIndex * itemWidthPercent}%)`;
			}


			window.ccOpenModal = function(imgElement) {
				const allImages = getImages();

				currentModalIndex = Array.from(allImages).indexOf(imgElement);


				const hdSrc = imgElement.getAttribute('data-src') || imgElement.src;
				modalImg.src = hdSrc;


				modal.classList.add('active');
				document.body.style.overflow = 'hidden'; 
			}

			window.ccCloseModal = function() {
				modal.classList.remove('active');
				setTimeout(() => {
					modalImg.src = '';
				}, 300);
				document.body.style.overflow = '';
			}

			window.ccCloseOnBg = function(e) {
				if (e.target === modal) {
					ccCloseModal();
				}
			}

			window.ccMoveModal = function(direction) {
				const allImages = getImages();
				currentModalIndex += direction;


				if (currentModalIndex >= totalItems) currentModalIndex = 0;
				if (currentModalIndex < 0) currentModalIndex = totalItems - 1;

				const nextImg = allImages[currentModalIndex];
				const hdSrc = nextImg.getAttribute('data-src') || nextImg.src;


				modalImg.style.opacity = '0.5';
				modalImg.src = hdSrc;
				setTimeout(() => {
					modalImg.style.opacity = '1';
				}, 150);
			}


			document.addEventListener('keydown', function(e) {
				if (!modal.classList.contains('active')) return;
				if (e.key === 'Escape') ccCloseModal();
				if (e.key === 'ArrowLeft') ccMoveModal(-1);
				if (e.key === 'ArrowRight') ccMoveModal(1);
			});
		})();



			(function() {
				function initCollapsible() {
					const contentDiv = document.querySelector('.text-base.detail.content');
					if (!contentDiv) return;

					// Find all heading tags (h1, h2, h3, h4, h5, h6) within the content
					const allHeadings = contentDiv.querySelectorAll('h1, h2, h3, h4, h5, h6');
					if (allHeadings.length < 3) return; // No need to collapse if less than 3 headings

					// Create collapsible container starting from 3rd heading
					const collapsibleDiv = document.createElement('div');
					collapsibleDiv.className = 'collapsible-section collapsed';
					collapsibleDiv.id = 'collapsibleContent';

					// Move all content from 3rd heading onwards into collapsible div
					const thirdHeading = allHeadings[2];
					let currentNode = thirdHeading;
					const nodesToMove = [];

					while (currentNode) {
						nodesToMove.push(currentNode);
						currentNode = currentNode.nextElementSibling;
					}

					// Insert collapsible div before 3rd heading and move nodes into it
					thirdHeading.parentNode.insertBefore(collapsibleDiv, thirdHeading);
					nodesToMove.forEach(node => {
						collapsibleDiv.appendChild(node);
					});

					// Create show more/less button
					const buttonWrapper = document.createElement('div');
					buttonWrapper.className = 'show-more-btn-wrapper';

					const button = document.createElement('button');
					button.className = 'show-more-btn';
					button.innerHTML = '<span class="arrow">&#9662;</span> Show more';
					button.onclick = function() {
						const section = document.getElementById('collapsibleContent');
						const isCollapsed = section.classList.contains('collapsed');

						if (isCollapsed) {
							section.classList.remove('collapsed');
							section.classList.add('expanded');
							button.classList.add('expanded');
							button.innerHTML = '<span class="arrow">&#9652;</span> Show less';
						} else {
							section.classList.remove('expanded');
							section.classList.add('collapsed');
							button.classList.remove('expanded');
							button.innerHTML = '<span class="arrow">&#9662;</span> Show more';
						}
					};

					buttonWrapper.appendChild(button);
					collapsibleDiv.parentNode.insertBefore(buttonWrapper, collapsibleDiv.nextSibling);
				}

				// Initialize when DOM is ready
				if (document.readyState === 'loading') {
					document.addEventListener('DOMContentLoaded', initCollapsible);
				} else {
					initCollapsible();
				}
			})();

                 What is Yovid? 
                 
 Seedance 2.5 on Yovid produces continuous 4-to-30-second video clips featuring native dialogue, environmental room tone, and sound effects rendered directly alongside the visuals. By pairing a timeline slider with an input capacity of up to 40 visual references, it removes the need to stitch multi-clip fragments together or manually align external audio tracks for dialogue scenes. Creators can rough out scenes at 480p and commit the confirmed composition to a final 1080p render without shifting the visual contents of the take. 
 Key Features Integrated Audio and Dialogue Synthesis : Generate spoken lines in quotation marks, ambient room tone, and sound effects within the same render pass -> Eliminates post-generation audio synchronization and external sound design for basic blocking. Natural-Language Clip Editing : Upload existing footage and describe exact modifications—such as swapping props, replacing outfits, or altering backgrounds—while retaining untouched camera moves and subject staging -> Removes the need to re-roll full generations to fix isolated visual details. Context-Preserving Clip Extensions : Extend uploaded footage by entering continuation prompts that maintain characters, environment geometry, and prop placement from the original clip's final frame -> Solves continuity breaks and character drift when sequencing scenes across cuts. Two-Stage Draft Workflow : Render scene previews at 480p and upgrade approved generations directly to 1080p using the identical seed composition within a 24-hour window -> Eliminates the visual uncertainty of re-generating full-resolution takes from scratch. Continuous Thirty-Second Narrative Arcs 
 Instead of generating disconnected 5-to-15-second fragments and assembling them in editing software, creators can define complete dramatic sequences—including a setup, turn, and payoff—within a single 30-second take. Because the entire duration renders in one pass, facial geometry, set lighting, and background blocking remain stable from the opening frame to the cut. The integrated audio engine tracks the physical action directly, anchoring dialogue lines, footsteps, and environmental cues to visible screen events without separate track mapping. 
 Forty Reference Slots and In-Place Editing 
 Unlike Kling 3.0, Veo 3.1 Fast, MiniMax H3, and Wan 3.0 on Yovid—which cap reference inputs at 15 combined items or accept none—Seedance 2.5 accepts up to 30 images and 10 video clips directly in the composer workspace. Each asset can be targeted individually via prompt tags (such as  @image1  for a specific character design or  @video1  for camera motion) to guide composition, live-action green-screen replacement, and 3D animatic previs. Furthermore, it is the only model in the workspace lineup to support direct in-place editing and extension of uploaded video files through plain-text instructions. 
 FAQ 
 What are the maximum resolution and export specifications? Seedance 2.5 exports MP4 video in 480p, 720p, or 1080p resolutions across seven frame formats: 16:9, 9:16, 1:1, 4:3, 3:4, 21:9, and an adaptive ratio based on input reference images. Reaching 4K requires running exported 1080p files through an external video upscaler. 
 How are audio references handled? While text-prompted dialogue and effects generate natively in the browser composer, providing external audio files as style, voice, or tempo references is restricted to API integration, which accepts up to 10 audio references. 
 What is the draft upgrade window? A 480p preview can be upgraded to the final 1080p render for up to 24 hours after the initial draft finishes processing. 







